const $=id=>document.getElementById(id);
const presets=[['Lime','#c4f568'],['Amber','#ffc45c'],['Cyan','#69e6f5'],['Pink','#f58bcb'],['Red','#ff665c'],['White','#ffffff']];
const defaults={message:'COME OVER?',size:100,color:'#c4f568',font:'solid',flash:!matchMedia('(prefers-reduced-motion: reduce)').matches,pace:1800,glow:12,uppercase:true};
let saved={};try{saved=JSON.parse(localStorage.getItem('signal-settings')||'{}')}catch{}
const state={...defaults,...saved};
state.message=String(state.message).slice(0,120);state.size=Math.min(100,Math.max(25,Number(state.size)||100));state.glow=Math.min(30,Math.max(0,Number(state.glow)||0));if(!/^#[0-9a-f]{6}$/i.test(state.color))state.color=defaults.color;if(![1200,1800,2400].includes(state.pace))state.pace=1800;if(!['solid','dots'].includes(state.font))state.font='solid';
let presenting=false,previewPaused=false,wakeLock=null,hideTimer,toastTimer,displayPaused=false;
function persist(){try{localStorage.setItem('signal-settings',JSON.stringify(state))}catch{}}
function colorName(){return presets.find(p=>p[1]===state.color.toLowerCase())?.[0]||'Custom'}
function sync(){
 $('count').textContent=`${state.message.length} / 120`;$('sizeValue').textContent=state.size+'%';$('colorName').textContent=colorName().toUpperCase();$('hex').textContent=state.color.toUpperCase();$('customColor').value=state.color;$('glowValue').textContent=state.glow===0?'Off':state.glow<16?'Soft':'Radiant';$('paceValue').textContent=(state.pace/1000)+' sec';$('modeLabel').textContent=`${state.flash?'FLASH':'STEADY'} · ${colorName().toUpperCase()}`;$('show').disabled=!state.message.trim();
 document.querySelectorAll('[data-color]').forEach(b=>{let active=b.dataset.color===state.color.toLowerCase();b.setAttribute('aria-pressed',active);b.textContent=active?'✓':''});
 document.querySelectorAll('[data-font]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.font===state.font));document.querySelectorAll('[data-pace]').forEach(b=>{b.setAttribute('aria-pressed',+b.dataset.pace===state.pace);b.disabled=!state.flash});
 persist();drawAll();
}
for(const [name,color] of presets){let b=document.createElement('button');b.className='swatch';b.style.setProperty('--swatch',color);b.dataset.color=color;b.setAttribute('aria-label',name);b.onclick=()=>{state.color=color;sync()};$('swatches').append(b)}
for(const k of ['message','size','glow','uppercase','flash']){const el=$(k);if(el.type==='checkbox')el.checked=state[k];else el.value=state[k];el.addEventListener('input',()=>{state[k]=el.type==='checkbox'?el.checked:el.type==='range'?+el.value:el.value;sync()})}
$('customColor').oninput=e=>{state.color=e.target.value;sync()};
document.querySelectorAll('[data-font]').forEach(b=>b.onclick=()=>{state.font=b.dataset.font;sync()});document.querySelectorAll('[data-pace]').forEach(b=>b.onclick=()=>{state.pace=+b.dataset.pace;sync()});
function selectTab(b){document.querySelectorAll('[data-tab]').forEach(t=>{let active=t===b;t.setAttribute('aria-selected',active);t.tabIndex=active?0:-1;$(t.dataset.tab+'-panel').hidden=!active})}
document.querySelectorAll('[data-tab]').forEach((b,i,all)=>{b.onclick=()=>selectTab(b);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let j=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;selectTab(all[j]);all[j].focus()}}});
document.querySelectorAll('[data-phrase]').forEach(b=>b.onclick=()=>{state.message=b.dataset.phrase;$('message').value=state.message;sync()});$('clear').onclick=()=>{state.message='';$('message').value='';$('message').focus();sync()};
$('previewPause').onclick=()=>{previewPaused=!previewPaused;$('previewPause').textContent=previewPaused?'▷ Resume preview':'Ⅱ Pause preview';$('previewPause').setAttribute('aria-pressed',previewPaused)};
function linesFor(ctx,text,size,maxWidth){ctx.font=`900 ${size}px Arial, sans-serif`;const result=[];for(const para of text.split('\n')){let line='';for(const word of para.split(/\s+/)){if(!word)continue;const candidate=line?line+' '+word:word;if(ctx.measureText(candidate).width<=maxWidth){line=candidate}else{if(line)result.push(line);line='';for(const char of word){if(ctx.measureText(line+char).width>maxWidth&&line){result.push(line);line=char}else line+=char}}}result.push(line)}return result}
function draw(canvas){let rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const ratio=Math.min(devicePixelRatio||1,2);const w=rect.width,h=rect.height;canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);let ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);let text=state.uppercase?state.message.toUpperCase():state.message;canvas.setAttribute('aria-label',text||'Empty banner');if(!text.trim())return;let maxWidth=w*.86,maxHeight=h*(canvas.id==='preview'?.72:.82),lo=1,hi=Math.min(h,900),size=1;while(hi-lo>.3){let mid=(lo+hi)/2;let lines=linesFor(ctx,text,mid,maxWidth);if(lines.length*mid*1.12<=maxHeight&&lines.every(l=>ctx.measureText(l).width<=maxWidth)){size=mid;lo=mid}else hi=mid}size*=state.size/100;let lines=linesFor(ctx,text,size,maxWidth);let layer=document.createElement('canvas');layer.width=canvas.width;layer.height=canvas.height;let lc=layer.getContext('2d');lc.scale(ratio,ratio);lc.font=`900 ${size}px Arial, sans-serif`;lc.textAlign='center';lc.textBaseline='middle';lc.fillStyle=state.color;const height=lines.length*size*1.12;lines.forEach((line,i)=>lc.fillText(line,w/2,(h-height)/2+size*1.12*(i+.5)));
 if(state.font==='dots'){lc.globalCompositeOperation='source-in';lc.fillStyle=state.color;let dots=document.createElement('canvas');let step=Math.max(3,Math.min(7,size/13));dots.width=Math.ceil(step*ratio);dots.height=dots.width;let dc=dots.getContext('2d');dc.fillStyle=state.color;dc.beginPath();dc.arc(dots.width/2,dots.height/2,dots.width*.35,0,Math.PI*2);dc.fill();lc.setTransform(1,0,0,1,0,0);lc.fillStyle=lc.createPattern(dots,'repeat');lc.fillRect(0,0,layer.width,layer.height)}
 ctx.shadowColor=state.color;ctx.shadowBlur=state.glow;ctx.drawImage(layer,0,0,w,h);ctx.shadowBlur=0;ctx.drawImage(layer,0,0,w,h);
}
function drawAll(){draw($('preview'));if(presenting)draw($('display'))}
new ResizeObserver(drawAll).observe($('preview').parentElement);
window.addEventListener('resize',drawAll);document.fonts?.ready.then(drawAll);
function tick(time){const lit=!state.flash||time%state.pace<state.pace*.72;$('preview').style.opacity=previewPaused||lit?'1':'0';if(presenting)$('display').style.opacity=displayPaused||lit?'1':'0';requestAnimationFrame(tick)}requestAnimationFrame(tick);
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3500)}
async function keepAwake(){if('wakeLock'in navigator&&presenting){try{wakeLock=await navigator.wakeLock.request('screen')}catch{}}}
function showControls(){clearTimeout(hideTimer);$('displayControls').classList.remove('hide');hideTimer=setTimeout(()=>{if(!$('displayControls').contains(document.activeElement))$('displayControls').classList.add('hide')},3000)}
$('show').onclick=async()=>{if(!state.message.trim())return;presenting=true;displayPaused=false;$('steady').textContent=state.flash?'Pause flashing':'Steady mode';$('steady').hidden=!state.flash;$('presentation').hidden=false;document.querySelector('.app').inert=true;drawAll();showControls();try{await $('presentation').requestFullscreen?.()}catch{}try{await screen.orientation?.lock('landscape')}catch{}keepAwake();drawAll();$('exit').focus();toast('Turn up your phone brightness for the clearest message.');setTimeout(()=>{if(document.activeElement===$('exit'))$('exit').blur()},1800)};
async function exit(){if(!presenting)return;presenting=false;clearTimeout(hideTimer);$('presentation').hidden=true;document.querySelector('.app').inert=false;try{screen.orientation?.unlock()}catch{}try{if(document.fullscreenElement)await document.exitFullscreen()}catch{}try{await wakeLock?.release()}catch{}wakeLock=null;$('show').focus();drawAll()}
$('exit').onclick=e=>{e.stopPropagation();exit()};$('steady').onclick=e=>{e.stopPropagation();displayPaused=!displayPaused;$('steady').textContent=displayPaused?'Resume flashing':'Pause flashing';showControls()};$('presentation').onclick=showControls;$('presentation').onkeydown=showControls;document.addEventListener('keydown',e=>{if(e.key==='Escape')exit()});document.addEventListener('fullscreenchange',()=>{if(!document.fullscreenElement&&presenting)exit()});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')keepAwake()});
sync();
